// Voice-over lookup and timing rules. Pure: the cue table (VoiceCues) and the
// bank asset ids (VoiceBanks) are generated by tools/voice.py and injected, so
// specs can run with fake asset ids while the shipped banks are still empty.
//
// A line only plays when its recorded text is exactly the text on screen and
// its bank has an approved Roblox asset; anything else is silently skipped.
import { STORY } from "./RelayStory";
import { VOICE_BANK_ASSETS } from "./VoiceBanks";
import { VOICE_CUES, VoiceCue } from "./VoiceCues";

/** Seconds a beat or radio subtitle holds after its voice ends. */
export const VOICE_TAIL = 0.4;
/** A radio voice that waited in the queue longer than this is dropped (its subtitle still shows). */
export const VOICE_STALE_SECONDS = 4;
/** Effects and engine sit this far under a speaking voice. */
export const VOICE_DUCK_DB = -6;

export interface VoiceClip {
	id: string;
	assetId: string;
	/** Region of the bank, seconds. */
	start: number;
	finish: number;
	seconds: number;
	speaker: string;
	tape: boolean;
	radio: boolean;
}

/** Stable id of a cutscene beat: chapter and beat index (0-based), as tools/voice-lines.ts writes them. */
export function storyLineId(chapter: number, beat: number): string {
	return `story.c${string.format("%02d", chapter)}.b${string.format("%02d", beat)}`;
}

export class VoiceLibrary {
	private radioIndex?: Map<string, string>;
	public constructor(
		private readonly cues: Record<string, VoiceCue>,
		private readonly assets: Record<string, string>,
	) {}

	/** The clip for `id`, only if its transcript is exactly `text` and its bank is uploaded. */
	public Clip(id: string, text: string): VoiceClip | undefined {
		const cue = this.cues[id] as VoiceCue | undefined;
		if (!cue || cue.text !== text) return undefined;
		const assetId = this.assets[cue.bank] as string | undefined;
		if (assetId === undefined || assetId === "" || cue.finish <= cue.start) return undefined;
		return { id, assetId, start: cue.start, finish: cue.finish, seconds: cue.finish - cue.start, speaker: cue.speaker, tape: cue.tape, radio: cue.radio };
	}

	public Story(chapter: number, beat: number, text: string): VoiceClip | undefined {
		const authored = STORY[chapter]?.beats[beat];
		if (authored && authored.text === text) return this.Clip(storyLineId(chapter, beat), text) ?? (authored.recordingId === undefined ? undefined : this.Clip(authored.recordingId, text));
		return this.Clip(storyLineId(chapter, beat), text);
	}

	/**
	 * Line id for a radio line by its exact text. The table is generated from the
	 * catalog at build time, so this is an exact lookup, never fuzzy matching.
	 */
	public RadioId(text: string): string | undefined {
		if (!this.radioIndex) {
			const index = new Map<string, string>();
			for (const [id, cue] of pairs(this.cues)) if (cue.radio) index.set(cue.text, id as string);
			this.radioIndex = index;
		}
		return this.radioIndex.get(text);
	}

	public Radio(text: string): VoiceClip | undefined {
		const id = this.RadioId(text);
		return id === undefined ? undefined : this.Clip(id, text);
	}
}

export const Voice = new VoiceLibrary(VOICE_CUES, VOICE_BANK_ASSETS);

/** A cutscene beat lasts its reading time, or the voice plus a short tail when that is longer. */
export function cinematicBeatSeconds(readSeconds: number, voiceSeconds?: number): number {
	return voiceSeconds === undefined ? readSeconds : math.max(readSeconds, voiceSeconds + VOICE_TAIL);
}

/** Linear gain for effects and engine: -6 dB while a voice speaks. */
export function duckGain(speaking: boolean): number {
	return speaking ? 10 ** (VOICE_DUCK_DB / 20) : 1;
}
